"""Normal ME3 conversation interface with owner-click artifact delivery."""
HTML='<!doctype html>\n<html lang="en">\n<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="me3-csrf" content="__CSRF__"><title>ME3</title><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head>\n<body>\n<main class="app">\n  <header><a href="/" class="brand" aria-label="ME3 home">ME3<span class="brand-dot"></span></a><div class="session-state" role="status"><i id="connection-dot"></i><span id="status">Connecting…</span></div><button id="stop" class="quiet" hidden>Stop</button><button id="artifacts" type="button" class="quiet" aria-controls="artifact-panel">Artifacts</button><button id="clear" class="quiet" aria-label="New conversation" title="Archive this conversation and start a new one">New conversation</button></header>\n  <section class="conversation" aria-label="Conversation">\n    <div id="empty" class="empty"><div class="wave" aria-hidden="true"><b></b><b></b><b></b><b></b><b></b><b></b><b></b></div><h1>What\'s on your mind today?</h1></div>\n    <div id="messages" aria-live="polite" aria-relevant="additions text"></div>\n  </section>\n  <section id="tasks" class="tasks" aria-label="Task progress" hidden><div class="task-heading">Tasks</div><ol id="task-list" aria-live="polite"></ol></section>\n  <section id="reminders" class="alerts" aria-label="Reminders" hidden></section>\n  <div id="notice" class="notice" role="status" hidden></div>\n  <form id="composer" class="composer"><label class="sr-only" for="message">Message ME3</label><textarea id="message" rows="1" maxlength="4000" placeholder="Type a message…"></textarea><div class="input-actions"><button id="voice" type="button" class="icon microphone" aria-label="Start voice conversation" title="Start voice conversation"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></svg></button><button id="send" type="submit" class="icon send" aria-label="Send message" title="Send message"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7"/></svg></button></div></form>\n</main>\n<dialog id="artifact-panel" aria-labelledby="artifact-title">\n  <div class="artifact-toolbar"><h2 id="artifact-title">Artifacts</h2><button id="artifact-refresh" type="button">Refresh files</button><button id="artifact-zip" type="button" disabled>Download project ZIP</button><button id="artifact-close" type="button" aria-label="Close artifacts">Close</button></div>\n  <p id="artifact-notice" role="status">Files from your Pi artifact workspace.</p>\n  <div class="artifact-content"><ul id="artifact-list" aria-label="Artifact files"></ul><section class="artifact-preview" aria-label="Selected artifact preview"><p id="artifact-selected">Choose an HTML file to preview.</p><iframe id="artifact-frame" title="Isolated artifact preview" sandbox="allow-scripts" allow="camera \'none\'; microphone \'none\'; geolocation \'none\'; autoplay \'none\'; payment \'none\'; usb \'none\'" referrerpolicy="no-referrer" hidden></iframe></section></div>\n  <p class="artifact-warning">Interactive HTML runs only in an isolated preview. Network APIs, external assets and access to ME3 are blocked; generated JavaScript may still navigate its own frame. Download Python files to use them separately.</p>\n</dialog>\n</body></html>\n'
